import networkx as nx,pickle
atlas=nx.graph_atlas_g()
def strip(G):
 G=G.copy();G.remove_nodes_from(list(nx.isolates(G)));return nx.convert_node_labels_to_integers(G)
# all atlas types without isolates, up to 7
Ts=[]; key={}
for G in atlas:
 if len(G) and min(dict(G.degree()).values(),default=0)==0:continue
 k=(len(G),G.number_of_edges(),tuple(sorted(dict(G.degree()).values())))
 if any(nx.is_isomorphic(G,Ts[i]) for i in key.get(k,[])):continue
 key.setdefault(k,[]).append(len(Ts));Ts.append(G)
def typ(G):
 G=strip(G);k=(len(G),G.number_of_edges(),tuple(sorted(dict(G.degree()).values())))
 return next(i for i in key[k] if nx.is_isomorphic(G,Ts[i]))
C=[i for i,G in enumerate(Ts) if len(G)<=5]
contains={}
for t,F in enumerate(Ts):
 contains[t]=sum(1<<j for j,i in enumerate(C) if len(F)<=len(Ts[i]) and F.number_of_edges()<=Ts[i].number_of_edges() and nx.algorithms.isomorphism.GraphMatcher(Ts[i],F).subgraph_is_monomorphic())
Hs=[]
for G in atlas:
 n=len(G)
 if n<3 or nx.is_bipartite(G):continue
 if not any(nx.is_bipartite(G.subgraph([u for u in G if u!=v])) for v in G):continue
 decomp=set()
 for A in range(1<<n):
  U=[u for u in G if A>>u&1];V=[u for u in G if not A>>u&1]
  decomp.add((typ(G.subgraph(U)),typ(G.subgraph(V))))
 if not any(len(Ts[a])==2*Ts[a].number_of_edges() and b==0 for a,b in decomp):continue
 # allowed companion candidate masks
 allow=[(1<<len(C))-1 for _ in C]
 for a,b in decomp:
  ma=contains[a];mb=contains[b]
  while ma:
   bit=ma&-ma;ma-=bit;j=bit.bit_length()-1
   allow[j]&=~mb
 pairs=[]
 for j,mask in enumerate(allow):
  for k in range(len(C)):
   if mask>>k&1:pairs.append((Ts[C[j]].number_of_edges(),Ts[C[k]].number_of_edges(),j,k))
 me=max(a+b for a,b,j,k in pairs)
 # cycle weights for larger vs smaller part at odd n: I0(2)/I2(2) ~3.308...
 w=3.308789373
 mw=max(w*a+b for a,b,j,k in pairs)
 if not any(a+b==me and abs(w*a+b-mw)<1e-8 for a,b,j,k in pairs):
  Hs.append((G,me,mw,[(a,b) for a,b,j,k in pairs if a+b==me],[(a,b) for a,b,j,k in pairs if abs(w*a+b-mw)<1e-8]))
print('potential counterexamples',len(Hs))
for G,me,mw,p1,p2 in Hs[:10]:print('H',len(G),list(G.edges()),'edge',me,set(p1),'cycle',set(p2))
pickle.dump(Hs,open('potential.pkl','wb'))

