 for j,mask in allow.items():
  if not mask:continue
  # only maximum number of edges of companion matters for either objective
  k=max((k for k in ids if mask>>k&1),key=lambda k:Ts[k].number_of_edges())
  a=Ts[j].number_of_edges();b=Ts[k].number_of_edges();e=a+b;c=w*a+b
  if e>me:me=e;ew=[(a,b)]
  elif e==me:ew.append((a,b))
  if c>mw+1e-8:mw=c;cw=[(a,b)]
  elif abs(c-mw)<1e-8:cw.append((a,b))
