import networkx as nx,itertools,pickle
out=[]
for G in nx.graph_atlas_g():
 n=len(G)
 if n<3 or nx.is_bipartite(G):continue
 # best odd-cycle edge transversal after deleting a vertex
 vals=[]
 for v in G:
  R=[u for u in G if u!=v];best=100
  for mask in range(1<<len(R)):
   U={R[i] for i in range(len(R)) if mask>>i&1}
   val=sum((a in U)==(b in U) for a,b in G.edges() if a!=v and b!=v)
   best=min(best,val)
  vals.append(best)
 if min(vals)<2:continue
 forests=[]
 for mask in range(1<<n):
  U=[u for u in G if mask>>u&1];V=[u for u in G if not mask>>u&1]
  if G.subgraph(V).number_of_edges():continue
  F=G.subgraph(U)
  if nx.is_forest(F):forests.append(F.copy())
